// Hand-written `koa` stub for the flowatlas fixture suite.
//
// One context per request: a body parser puts the body on `ctx.request.body`,
// untyped, and the answer is whatever is assigned to `ctx.body`.

export interface ParsedUrlQuery {
  [key: string]: string | string[] | undefined;
}

export interface IncomingHttpHeaders {
  host?: string;
  [header: string]: string | string[] | undefined;
}

export interface Context {
  request: { body?: unknown };
  params: Record<string, string>;
  query: ParsedUrlQuery;
  headers: IncomingHttpHeaders;
  status: number;
  body: unknown;
}

export type Next = () => Promise<void>;

export type Middleware = (ctx: Context, next: Next) => unknown;

declare class Application {
  use(middleware: Middleware): Application;
  listen(port: number): unknown;
}

export default Application;
